latform-chip{color:#ff681c}.settings-row{display:grid;grid-template-columns:1fr 1.5fr 150px;gap:18px;align-items:end;margin-top:16px}.money-input{height:44px;border:1px solid #dde5ec;border-radius:10px;display:flex;align-items:center;padding:0 12px}.money-input input{border:0;outline:0;width:100%}.days-options{display:flex;gap:8px}.days-options button{height:44px;min-width:76px;border:1px solid #dce4eb;background:#fff;border-radius:10px}.days-options button.active{color:#ff681c}.start-btn{height:46px}.notice{color:#d65b18}.fine-print{color:#8a98a7;font-size:12px}.content-grid{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:18px}.monitor-panel{min-height:390px;overflow:hidden}.tabs{height:58px;border-bottom:1px solid #edf1f5}.tabs button{height:58px;border:0;background:none;color:#ff681c;font-weight:700}.empty-state{height:330px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#7f8e9e}.watch-list{padding:8px 20px}.watch-item{display:grid;grid-template-columns:54px minmax(240px,1fr) 90px 90px 80px 96px;gap:12px;align-items:center;padding:15px 0;border-bottom:1px solid #edf1f5}.watch-item.unavailable{opacity:.72}.item-thumb-image{object-fit:cover}.item-main{display:flex;flex-direction:column;gap:5px;min-width:0}.item-title-row{display:flex;gap:8px;flex-wrap:wrap}.unavailable-chip{font-size:11px;color:#c34848}.item-main a{font-size:12px;color:#527a9d;overflow:hidden;text-overflow:ellipsis}.item-main span,.metric span{font-size:11px;color:#8998a7}.metric{display:flex;flex-direction:column;gap:5px}.muted{color:#97a4af}.unavailable-text{color:#c34848}.item-actions{display:flex;flex-direction:column;gap:6px}.history-btn,.remove-btn{border:1px solid #e1e8ee;background:#fff;border-radius:9px;padding:7px 8px;cursor:pointer;font-size:12px}.history-btn{color:#ff681c}.guide-panel{padding:20px}.guide-title{font-weight:800}.guide-panel li{margin-bottom:14px}.guide-panel li span,.tip span{display:block;font-size:12px;color:#8494a4}.tip{border-top:1px solid #edf1f5;padding-top:16px}.modal-mask{position:fixed;inset:0;z-index:2000;background:rgba(20,31,43,.48);display:grid;place-items:center;padding:24px}.history-modal{width:min(900px,96vw);max-height:90vh;overflow:auto;background:#fff;border-radius:18px;padding:24px}.modal-head{display:flex;justify-content:space-between}.modal-head h2{margin:0}.modal-head p{color:#8593a1;font-size:13px}.close-btn{border:0;background:#f3f6f8;border-radius:50%;width:34px;height:34px;font-size:24px}.history-summary{display:flex;align-items:end;gap:24px;margin-top:20px;padding:14px 16px;background:#fafbfd;border:1px solid #edf1f5;border-radius:12px}.history-summary>div:not(.range-tabs){display:flex;flex-direction:column;gap:3px}.history-summary span{font-size:12px;color:#8695a4}.history-summary b{font-size:16px}.range-tabs{margin-left:auto;display:flex;gap:6px}.range-tabs button{border:1px solid #dde5ec;background:#fff;border-radius:8px;padding:7px 12px}.range-tabs button.active{color:#ff681c;border-color:#ff681c}.chart-wrap{margin-top:16px}.price-chart{display:block;width:100%;height:auto;min-height:300px}.grid-line{stroke:#edf1f5}.axis-label{fill:#8997a5;font-size:11px}.price-line{fill:none;stroke:#ff681c;stroke-width:3}.price-dot{fill:#fff;stroke:#ff681c;stroke-width:3}.price-dot-hit{fill:transparent;stroke:transparent;cursor:pointer}.purchase-line{stroke:#8293a3;stroke-width:1.5;stroke-dasharray:6 5}.purchase-label{fill:#657786;font-size:11px}.hover-guide{stroke:#ffb98f;stroke-width:1;stroke-dasharray:3 3}.tooltip-bg{fill:#26384a;filter:drop-shadow(0 3px 6px rgba(0,0,0,.18))}.tooltip-date{fill:#dbe5ee;font-size:10px}.tooltip-price{fill:#fff;font-size:13px;font-weight:700}.chart-note{text-align:center;color:#8997a5;font-size:12px}.chart-state{height:300px;display:grid;place-items:center;color:#8493a2}.chart-state.error{color:#c34848}@media(max-width:980px){.hero{grid-template-columns:1fr}.hero-visual,.feature-list{display:none}.settings-row,.content-grid{grid-template-columns:1fr}.watch-item{grid-template-columns:54px minmax(0,1fr) 90px 96px}.watch-item .metric:nth-of-type(n+2){display:none}.history-summary{flex-wrap:wrap}.range-tabs{margin-left:0}}@media(max-width:680px){.price-watch-page{padding:78px 12px 30px}.watch-item{grid-template-columns:44px minmax(0,1fr) 86px}.watch-item .metric{display:none}.guide-panel{display:none}.history-modal{padding:18px}.range-tabs{width:100%}.range-tabs button{flex:1}.price-chart{min-height:230px}}
</style>